import { analyzeCart, analysisDataset, products, normalizeCart, getReplacementCandidates, compareAnalyses, SCORING_POLICY } from './data/analysis.js';
const $ = s => document.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = { home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z', search:'M21 21l-5-5M10.5 18a7.5 7.5 0 1 0 0-15 7.5 7.5 0 0 0 0 15', bag:'M5 7h14l1 14H4L5 7ZM9 8V6a3 3 0 0 1 6 0v2', bookmark:'M6 3h12v18l-6-4-6 4V3Z', arrow:'M4 12h16m-6-6 6 6-6 6', back:'M20 12H4m6-6-6 6 6 6', plus:'M12 5v14M5 12h14', check:'m5 12 4 4L19 6', chevron:'m9 5 7 7-7 7', x:'m6 6 12 12M6 18 18 6', info:'M12 8h.01M12 11v6M22 12a10 10 0 1 0-20 0 10 10 0 0 0 20 0', warning:'M12 8v5m0 3h.01M10 3 2 18a2 2 0 0 0 2 3h16a2 2 0 0 0 2-3L14 3a2 2 0 0 0-4 0', refresh:'M20 7V3l-4 4M4 17v4l4-4M20 7a9 9 0 0 0-15 0M4 17a9 9 0 0 0 15 0', minus:'M5 12h14', grid:'M3 3h7v7H3ZM14 3h7v7h-7ZM3 14h7v7H3ZM14 14h7v7h-7Z', external:'M14 3h7v7m0-7L10 14M10 3H3v18h18v-7' };
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name] || paths.info}"/></svg>`;
const byId = new Map(products.map(p => [p.product_id, p]));
const KEY='fitmate-v3-design-prototype';
let storageAvailable = true;
function readStore(){try{return JSON.parse(localStorage.getItem(KEY) || 'null')}catch{storageAvailable=false;return null}}
const stored=readStore();
let cart = stored && Array.isArray(stored.cart) ? normalizeCart(stored.cart) : [{productId:'P02',quantity:1},{productId:'M02',quantity:1}];
let saved = Array.isArray(stored?.saved) ? stored.saved.filter(s => s && typeof s.name==='string' && Array.isArray(s.items)).map(s=>({...s,items:normalizeCart(s.items)})).filter(s=>s.items.length) : [];
let screen='home', query='', category='전체', medications=false, listSort='default', homeTab='supplement', previousCart=[], undoCart=null, toastTimer, sheetOpener, sheetScroll=0, gaugeFrame=0, lastGaugeValue=null;
const reduced = matchMedia('(prefers-reduced-motion: reduce)');
let selectedCause=null, explanation=null, replacementSource=null, replacementTarget=null, comparisonFrame=0, renderedScreen=null, exploreReturn='home', exploreReturnScroll=0;
const examples=[{id:'routine',title:'나의 기본 구성 살펴보기',description:'프로틴 · 마그네슘 · 종합비타민',ids:['P01','P06','P08']},{id:'duplicate',title:'겹치는 성분이 궁금하다면',description:'종합비타민 · 비타민 D',ids:['P08','P09']}];
const itemsFor = ids => ids.map(productId=>({productId,quantity:1}));
const result = () => analyzeCart(cart,analysisDataset);
const imagePath = p => `./assets${p.image}`;
const thumb = (p, cls='') => `<span class="product-thumb ${cls}"><img src="${imagePath(p)}" alt="" draggable="false">${/^P0[123]$/.test(p.product_id)?`<span class="variant-tag">${p.product_id.slice(-1)==='1'?'A':p.product_id.slice(-1)==='2'?'B':'C'}</span>`:''}</span>`;
function persist(){try{localStorage.setItem(KEY,JSON.stringify({cart,saved}));return true}catch{storageAvailable=false;return false}}
function toast(text,undo=false){clearTimeout(toastTimer);$('#toast').innerHTML=`${esc(text)}${undo?'<button data-action="undo">되돌리기</button>':''}`;$('#toast').className=`toast visible ${screen==='cart'?'above-dock':''}`;toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),undo?8000:3500)}
function announce(text){$('#announcement').textContent='';requestAnimationFrame(()=>$('#announcement').textContent=text)}
function navigation(){const count=cart.reduce((n,i)=>n+i.quantity,0);$('#navigation').innerHTML=[['home','홈','home'],['explore','탐색','search'],['cart','조합함','bag'],['saved','내 정보','bookmark']].map(([id,label,symbol])=>`<a class="nav-item" href="#${id}" ${screen===id || (['analysis','optimize'].includes(screen)&&id==='cart')?'aria-current="page"':''}><span class="nav-icon">${icon(symbol)}${id==='cart'&&count?`<span class="count-badge">${count}</span>`:''}</span>${label}</a>`).join('')}
function productRow(p,index=null){const inCart=cart.some(i=>i.productId===p.product_id);return `<li class="product-row">${index!==null?`<span class="row-index">${String(index+1).padStart(2,'0')}</span>`:''}<button class="product-open" data-action="product" data-id="${p.product_id}" aria-label="${esc(p.name)} 상세 보기">${thumb(p)}<span class="product-copy"><strong>${esc(p.name)}</strong><p>${esc(p.subtitle)}</p><small>DEMO · 함량 미등록</small></span></button><button class="add-button ${inCart?'is-added':''}" data-action="${inCart?'cancel-add':'add'}" data-id="${p.product_id}" aria-label="${esc(p.name)} ${inCart?'담기 취소':'조합함에 담기'}" title="${inCart?'담기 취소':'조합함에 담기'}" aria-pressed="${inCart}">${icon(inCart?'check':'plus')}${inCart?'<span>취소</span>':''}</button></li>`}
function topbar(title,back=false,right=''){const destination=typeof back==='string'?back:'cart';return `<header class="topbar"><div class="topbar-title">${back?`<button class="icon-button back" data-action="go" data-id="${destination}" aria-label="이전 화면으로 돌아가기">${icon('back')}</button>`:''}<h1>${title}</h1></div>${right}</header>`}
function home(){const r=analyzeCart(itemsFor(examples[0].ids),analysisDataset);const current=products.filter(p=>p.category==='supplement'&&(homeTab==='supplement'?p.group==='프로틴':['P06','P08','P09'].includes(p.product_id))).slice(0,3);return `<section class="screen home-screen" aria-label="Fitmate 홈"><header class="topbar"><a class="wordmark" href="#home">Fitmate<span>.</span></a><button class="icon-button" data-action="go" data-id="cart" aria-label="조합함 열기">${icon('bag')}<span class="count-badge">${cart.reduce((n,i)=>n+i.quantity,0)}</span></button></header><div class="welcome"><h1>나의 영양 루틴,<br>조합부터 살펴봐요.</h1><p>함께 먹는 제품, 성분부터 차근차근.</p></div><form class="search-field" data-form="home-search" role="search">${icon('search')}<input name="query" type="search" placeholder="제품이나 성분을 검색해보세요" aria-label="홈 제품 또는 성분 검색"><button class="icon-button" aria-label="검색하기">${icon('arrow')}</button></form><div class="shortcut-grid" aria-label="카테고리 바로가기">${[['프로틴','white-jar-demo.png','프로틴'],['비타민·미네랄','amber-bottle-demo.png','비타민&미네랄'],['카페인','mockups/energy.webp','카페인'],['전체 제품','','전체']].map(([label,img,id])=>`<button class="shortcut" data-action="category" data-id="${id}"><span class="shortcut-stage">${img?`<img src="./assets/images/${img}" alt="">`:icon('grid')}</span>${label}</button>`).join('')}</div><section class="section"><div class="section-heading"><h2>추천 조합 예시</h2><span class="badge">DEMO</span></div><button class="recommendation" data-action="example" data-id="routine"><span class="label">COMBINATION 01</span><h3>기본 구성 살펴보기</h3><p>프로틴 · 마그네슘<br>종합비타민</p><span class="recommendation-footer">비교 지표 ${r.score.value} <span aria-hidden="true">/ 100</span>${icon('arrow')}</span><span class="rec-images"><img src="./assets/images/white-jar-demo.png" alt=""><img src="./assets/images/charcoal-jar-demo.png" alt=""></span></button><button class="recommendation-secondary" data-action="example" data-id="duplicate"><span class="mini-images"><img src="./assets/images/amber-bottle-demo.png" alt=""><img src="./assets/images/amber-bottle-demo.png" alt=""></span><span><strong>겹치는 성분이 궁금하다면</strong><span class="meta">종합비타민 + 비타민 D</span></span>${icon('chevron')}</button><p class="section-note">구성을 살펴보는 예시이며, 복용 추천이 아니에요.</p></section><section class="section"><div class="section-heading"><h2>제품 둘러보기</h2><button class="text-button" data-action="category" data-id="전체">전체 보기 ${icon('arrow')}</button></div><div class="tabs" aria-label="제품 유형"><button data-action="home-tab" data-id="supplement" aria-pressed="${homeTab==='supplement'}">보충제</button><button data-action="home-tab" data-id="vitamin" aria-pressed="${homeTab==='vitamin'}">영양제</button></div><p class="section-note">카탈로그 기본순 · 번호는 인기 순위가 아니에요.</p><ol class="product-list">${current.map((p,i)=>productRow(p,i)).join('')}</ol></section><footer class="footer-note"><p>모든 제품은 가상의 시연용 구성이에요.<br>패키지는 기존 AI 목업 이미지예요.</p><button class="link-row" data-action="medications">복용 중인 약도 함께 확인하기 ${icon('arrow')}</button></footer></section>`}
function explore(){return `<section class="screen explore-screen">${topbar('제품 탐색',exploreReturn)}<div class="tabs" aria-label="탐색 대상"><button data-action="mode" data-id="supplement" aria-pressed="${!medications}">보충제·영양제</button><button data-action="mode" data-id="medication" aria-pressed="${medications}">복용약 확인</button></div><div style="height:20px"></div><form class="search-field" data-form="search" role="search">${icon('search')}<input id="catalog-search" type="search" value="${esc(query)}" placeholder="제품 또는 성분 검색" aria-label="제품 또는 성분 검색"><button class="icon-button" type="button" data-action="clear-search" aria-label="검색어 지우기">${icon('x')}</button></form><div style="height:17px"></div>${medications?'<p class="notice">복용 중인 약의 관계를 확인하는 목록이에요. 약을 임의로 변경하지 마세요.</p>':`<div class="chips" aria-label="제품 카테고리">${['전체','프로틴','비타민&미네랄','카페인'].map(c=>`<button class="chip" data-action="filter" data-id="${c}" aria-pressed="${category===c}">${c.replace('&','·')}</button>`).join('')}</div>`}<div id="catalog-results"></div><footer class="footer-note">DEMO · 등록된 제품과 성분만 표시해요.<br>등록 제품 17개 중 보충제·영양제 10개, 복용약 7개.</footer></section>`}
function updateCatalog(){const q=query.replace(/\s/g,'').toLowerCase();let visible=products.filter(p=>(medications?p.category==='medication':p.category==='supplement'&&(category==='전체'||p.group===category||(category==='카페인'&&p.ingredients.some(i=>i.ingredient_id==='caffeine'))))&&[p.name,p.subtitle,...p.ingredientNames,...p.ingredients.map(i=>i.ingredient_id)].join('').replace(/\s/g,'').toLowerCase().includes(q));if(listSort==='name')visible.sort((a,b)=>a.name.localeCompare(b.name,'ko'));$('#catalog-results').innerHTML=`<div class="catalog-header"><span role="status">${visible.length}개 제품</span><label><span class="sr-only">제품 정렬</span><select id="sort"><option value="default" ${listSort==='default'?'selected':''}>기본순</option><option value="name" ${listSort==='name'?'selected':''}>이름순</option></select></label></div>${visible.length?`<ul class="product-list">${visible.map(p=>productRow(p)).join('')}</ul>`:'<div class="empty-state"><h3>검색 결과가 없어요</h3><p>다른 제품명이나 성분으로 찾아보세요.</p><button class="secondary-button" data-action="clear-search">검색 초기화</button></div>'}`}
function render(){const focused=document.activeElement;const focusAction=focused?.dataset?.action,focusId=focused?.dataset?.id;screen=location.hash.slice(1)||'home';if(!['home','explore','cart','analysis','optimize','saved'].includes(screen))screen='home';$('#action-dock').innerHTML='';$('#main').innerHTML=screen==='home'?home():screen==='explore'?explore():renderFeature(screen);if(renderedScreen===screen)$('#main .screen').style.animation='none';renderedScreen=screen;navigation();if(screen==='explore')updateCatalog();afterRender();if(focusAction&&!$('#sheet').open){const next=[...document.querySelectorAll('[data-action]')].find(el=>el.dataset.action===focusAction&&el.dataset.id===focusId);next?.focus({preventScroll:true})}}
function navigate(id){if(location.hash===`#${id}`){render();window.scrollTo(0,0)}else location.hash=id}
function gauge(a){return `<div class="score-gauge" role="img" aria-label="시연 조합 비교 지표 ${a.score.value===null?'계산 정보 부족':a.score.value+' / 100'}. 의학적 안전도 아님"><svg viewBox="0 0 200 200" aria-hidden="true"><circle class="gauge-track" cx="100" cy="100" r="85"/><circle class="gauge-progress" cx="100" cy="100" r="85" pathLength="100" stroke-dasharray="100" stroke-dashoffset="100" transform="rotate(-90 100 100)"/></svg><div class="gauge-copy" aria-hidden="true"><span class="gauge-number" data-score="${a.score.value??''}">${a.score.value??'—'}</span><span class="gauge-denominator">/ 100</span><span class="gauge-caption">시연 비교 지표</span></div></div>`}
function cartRow(item){const p=byId.get(item.productId);return `<li class="cart-row" data-product="${p.product_id}"><button class="product-open" data-action="product" data-id="${p.product_id}" aria-label="${esc(p.name)} 상세 보기">${thumb(p)}<span class="product-copy"><strong>${esc(p.name)}</strong><p>${esc(p.subtitle)}</p></span></button><button class="icon-button remove-button" data-action="remove" data-id="${p.product_id}" aria-label="${esc(p.name)} 삭제">${icon('x')}</button><div class="quantity-row"><span class="meta">DEMO · 용기 수량</span><span class="stepper"><button data-action="quantity-minus" data-id="${p.product_id}" aria-label="${esc(p.name)} 수량 줄이기" ${item.quantity===1?'disabled':''}>${icon('minus')}</button><output aria-label="${esc(p.name)} 용기 수량">${item.quantity}</output><button data-action="quantity-plus" data-id="${p.product_id}" aria-label="${esc(p.name)} 수량 늘리기" ${item.quantity>=99?'disabled':''}>${icon('plus')}</button></span></div></li>`}
function cartScreen(){const a=result();const active=a.score.deductions.length;return `<section class="screen with-dock" aria-label="조합함">${topbar('조합함',false,`<span class="badge">DEMO · ${a.products.length}개 제품</span>`)}<div class="score-layout">${gauge(a)}<div class="score-summary"><span class="label">MY COMBINATION</span><h2>${a.score.value===null?'제품을 더 담아<br>비교해보세요':active?`확인할 성분 관계<br><span>${active}가지</span>가 있어요`:'등록된 주의 관계가<br>없어요'}</h2><p>중복 성분 ${a.duplicates.length}개</p><button class="text-button" data-action="score-guide">점수 계산 방식 ${icon('info')}</button></div></div><p class="score-disclaimer">의학적 안전도 아님 · 함량 미확인 ${a.coverage.unknownAmounts}건</p>${a.products.length>1?`<button class="attention-row ${active?'has-warning':''}" data-action="go" data-id="analysis"><span class="attention-icon">${icon(active?'warning':'info')}</span><span><strong>${active?esc(a.score.deductions[0].ingredientNames.join(' · ')):'등록된 규칙으로 비교했어요'}</strong><span>${active?'감점 이유와 상세 조건 확인':'100점도 안전성을 보장하지 않아요'}</span></span>${icon('chevron')}</button>`:''}<section class="section cart-products"><div class="section-heading"><h2>담긴 제품 <span class="heading-count">${a.products.length}</span></h2><button class="text-button" data-action="go" data-id="explore">제품 추가 ${icon('plus')}</button></div>${cart.length?`<ul class="product-list">${cart.map(cartRow).join('')}</ul><p class="section-note">용기 수량은 1일 섭취량이 아니에요.</p><div class="cart-analysis-actions"><button class="link-row" data-action="go" data-id="analysis">상세 정보 확인 ${icon('arrow')}</button><button class="secondary-button" data-action="go" data-id="optimize">최적화 분석 ${icon('arrow')}</button></div>`:`<div class="empty-state">${icon('bag')}<h3>나의 조합을 시작해보세요</h3><p>서로 다른 제품을 2개 이상 담으면<br>등록된 성분 관계를 비교할 수 있어요.</p><button class="primary-button" data-action="go" data-id="explore">제품 둘러보기 ${icon('arrow')}</button></div>`}</section></section>`}
function savedScreen(){return `<section class="screen">${topbar('내 정보')}<div class="section-heading"><h2>저장한 조합</h2><span class="meta">${saved.length}개</span></div><p class="body-muted">이 브라우저에 저장돼요. 복원할 때 현재 규칙으로 다시 계산해요.</p>${saved.length?saved.map(s=>{const a=analyzeCart(s.items,analysisDataset);return `<article class="saved-row"><div><span class="badge">DEMO</span><h3>${esc(s.name)}</h3><p>${s.items.length}개 제품 · 비교 지표 ${a.score.value??'—'}</p><p class="meta">${esc(s.items.map(i=>byId.get(i.productId).name).join(' · '))}</p></div><button class="secondary-button" data-action="restore" data-id="${esc(s.id)}">이 조합 복원하기 ${icon('refresh')}</button></article>`}).join(''):'<div class="empty-state"><h3>저장한 조합이 없어요</h3><p>조합함에서 이름을 붙여 저장해보세요.</p><button class="secondary-button" data-action="go" data-id="cart">조합함으로 가기</button></div>'}<p class="notice" style="margin-top:24px">개인별 복용량·체질은 판정하지 않아요. 이 프로토타입에는 로그인이나 서버 저장이 없어요.</p></section>`}
function renderFeature(name){return name==='cart'?cartScreen():name==='saved'?savedScreen():name==='analysis'?analysisScreen():optimizeScreen()}
function afterRender(){cancelAnimationFrame(gaugeFrame);if(screen==='cart'){const a=result();$('#action-dock').innerHTML=cart.length?`<div class="action-dock"><button class="primary-button" data-action="save">${icon('bookmark')}조합 저장하기</button></div>`:'';animateGauge(a.score.value)}afterAnalysisRender()}
function animateGauge(value){const number=$('[data-score]'),ring=$('.gauge-progress');if(!number||!ring)return;const from=lastGaugeValue??0;lastGaugeValue=value;if(value===null){number.textContent='—';ring.style.strokeDashoffset='100';return}const start=performance.now();function frame(now){const progress=reduced.matches?1:Math.min((now-start)/680,1);const eased=1-Math.pow(1-progress,3);const v=from+(value-from)*eased;number.textContent=Math.round(v);ring.style.strokeDashoffset=100-v;if(progress<1)gaugeFrame=requestAnimationFrame(frame)}gaugeFrame=requestAnimationFrame(frame)}
function findingFor(a,cause){return a.findings.find(f=>f.causeKey===cause)}
function relationSVG(f){const [idA,idB]=f.productIds;const pa=byId.get(idA);const left=pa.ingredients.some(i=>i.ingredient_id===f.ingredientIds[0])?0:1;const names=[f.ingredientNames[left],f.ingredientNames[1-left]];const isDuplicate=f.kind==='duplicate';return `<figure class="relation-figure"><svg class="relation-svg ${f.severity==='info'?'information':''}" viewBox="0 0 346 142" role="img" aria-label="${esc(names.join('와 '))}, ${esc(f.ruleId)} 규칙의 ${isDuplicate?'중복':'상호작용 검토'} 관계"><title>${esc(f.ruleId)} · ${esc(f.ingredientNames.join(' · '))}</title><path class="relation-track" d="M118 60C166 60 180 60 228 60"/><path class="relation-edge" d="M118 60C166 60 180 60 228 60" pathLength="100"/><circle class="relation-pulse" cx="173" cy="60" r="16"/><text class="relation-mark" x="173" y="66" text-anchor="middle">${isDuplicate?'=':'!'}</text><rect class="relation-node" x="0" y="29" width="118" height="62" rx="14"/><rect class="relation-node" x="228" y="29" width="118" height="62" rx="14"/><text class="relation-label" x="59" y="65" text-anchor="middle">${esc(names[0])}</text><text class="relation-label" x="287" y="65" text-anchor="middle">${esc(names[1])}</text><text class="relation-product" x="59" y="119" text-anchor="middle">${esc(byId.get(idA).name.replace(' 경구제','').replace(' 계열 등록 예시',''))}</text><text class="relation-product" x="287" y="119" text-anchor="middle">${esc(byId.get(idB).name.replace(' 경구제','').replace(' 계열 등록 예시',''))}</text></svg><figcaption>${isDuplicate?'서로 다른 제품에서 같은 성분을 확인했어요.':'선은 등록 규칙의 관계를 뜻하며, 발생 확률이 아니에요.'}</figcaption></figure>`}
function sourceLabel(url){const host=new URL(url).hostname.replace(/^www\./,'');return host.includes('dailymed')?'DailyMed · 등록 의약품 라벨':host==='ods.od.nih.gov'?'NIH ODS · 성분 자료':host.includes('efsa')?'EFSA · 등록 참고자료':host.includes('seoulmc')?'한국인 영양소 섭취기준 자료':host.includes('mfds')?'식품의약품안전처 · 등록 자료':host.includes('nhs')?'NHS · 등록 자료':host.includes('nccih')?'NCCIH · 등록 자료':host}
function sourcesHTML(f){return f.sourceUrls.length?`<ul class="source-list">${f.sourceUrls.map(url=>`<li><a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(sourceLabel(url))}${icon('external')}</a></li>`).join('')}</ul>`:'<p class="body-muted">이 규칙에는 출처 URL이 등록되지 않았어요.</p>'}
function relationSpotlight(a){const deduction=a.score.deductions.find(d=>d.causeKey===selectedCause)??a.score.deductions[0];if(!deduction)return `<div class="notice"><strong>${a.score.value===null?'비교할 제품 정보가 부족해요.':'매칭된 주의 규칙이 없어요.'}</strong><p>${a.score.value===null?'서로 다른 등록 제품 2개 이상을 담아주세요.':'현재 등록 규칙에 해당하지 않는다는 뜻이에요. 모든 성분 관계나 개인별 안전성을 확인한 것은 아니에요.'}</p></div>`;selectedCause=deduction.causeKey;const f=findingFor(a,deduction.causeKey);return `<article class="relation-spotlight"><div class="relation-heading"><span class="badge ${f.severity==='info'?'blue':'warn'}">${f.medicationRelated?'복용약 관련':f.kind==='duplicate'?'중복 확인':'상호작용 확인'} · ${esc(f.ruleId)}</span><span class="deduction">−${deduction.points}<small>점</small></span></div>${relationSVG(f)}<h3>${esc(f.title)}</h3><p class="rule-message">${esc(f.message)}</p><p class="condition-note">${icon('info')}<span>상세 조건 ${f.detailedEvaluation.status==='met'?'확인':'미확인'} · ${esc(f.detailedEvaluation.reason)}</span></p><button class="link-row" data-action="evidence" data-id="${f.ruleId}">이 관계의 출처와 적용 범위 ${icon('arrow')}</button></article>`}
function analysisScreen(){const a=result();const candidates=cart.flatMap(i=>getReplacementCandidates(cart,i.productId,analysisDataset));return `<section class="screen analysis-screen">${topbar('분석 상세',true,`<span class="badge">DEMO</span>`)}<div class="analysis-summary"><div><span class="label">COMBINATION REPORT</span><p><strong>${a.score.value??'—'}</strong><span>/ 100</span><span class="summary-subtitle">시연 비교 지표</span></p></div><button class="icon-button" data-action="score-guide" aria-label="점수 계산 가이드">${icon('info')}</button></div><p class="report-disclaimer">의학적 안전도 아님 · ${a.products.length}개 제품의 등록 성분 기준</p><section class="section"><div class="section-heading"><h2>확인할 성분 관계</h2><span class="meta">${a.score.deductions.length}가지 원인</span></div>${a.score.deductions.length>1?`<div class="chips" aria-label="성분 관계 선택">${a.score.deductions.map((d,i)=>{const f=findingFor(a,d.causeKey);return `<button class="chip" data-action="relation" data-id="${f.ruleId}" aria-pressed="${(selectedCause??a.score.deductions[0].causeKey)===d.causeKey}">${i+1}. ${esc(d.ingredientNames.join(' · '))}</button>`}).join('')}</div>`:''}${relationSpotlight(a)}</section><section class="section"><div class="section-heading"><h2>점수의 근거</h2><button class="text-button" data-action="score-guide">계산 방식 ${icon('info')}</button></div><div class="score-breakdown"><div><span>기준 점수</span><strong>${SCORING_POLICY.baseline}</strong></div>${a.score.deductions.map(d=>`<button data-action="evidence" data-id="${d.ruleIds[0]}"><span>${esc(d.ingredientNames[0]===d.ingredientNames[1]?`${d.ingredientNames[0]} 중복`:d.ingredientNames.join(' · '))}<small>${esc(d.ruleIds.join(', '))} · 고유 원인 1회 반영</small></span><strong>−${d.points}</strong></button>`).join('')}<div class="total"><span>시연 비교 지표${a.score.rawDeduction>100?' (최저 0점)':''}</span><strong>${a.score.value??'—'}</strong></div></div><p class="section-note">감점은 임상 위험 수치가 아닌 앱의 시연 정책이에요.</p></section><section class="section"><div class="section-heading"><h2>중복 성분</h2><span class="meta">${a.duplicates.length}개</span></div>${a.duplicates.length?a.duplicates.map(d=>`<div class="duplicate-row"><strong>${esc(d.name)}</strong><span>${d.productIds.length}개 제품에 포함</span><p>${esc(d.productIds.map(id=>byId.get(id).name).join(' · '))}</p><p>${d.ruleIds.length?`연결 규칙 ${esc(d.ruleIds.join(', '))}`:'등록된 감점 규칙 없음 · 관찰 정보'} · 총량은 미확인</p></div>`).join(''):'<p class="body-muted">등록 성분 기준으로 겹치는 성분이 없어요.</p>'}<p class="section-note">성분 중복만으로 과다 섭취를 판단하지 않아요.</p></section><section class="section improvement-section"><span class="label">NEXT STEP</span><h2>구성을 바꾸면 어떨까요?</h2><p>공통 등록 성분이 있는 보충제로<br>변경 전후의 관계를 비교해보세요.</p>${candidates.length?`<button class="primary-button" data-action="go" data-id="optimize">제품 교체 비교 ${icon('arrow')}</button>`:'<p class="notice">현재 조합에는 등록 성분 기준의 교체 후보가 없어요.</p>'}<p class="section-note">효능이 같거나 더 안전하다는 추천은 아니에요.</p></section><section class="section explanation-section" id="explanation"><div class="section-heading"><h2>분석을 쉽게 이해하기</h2><span class="badge blue">규칙 기반</span></div><p class="body-muted">AI API 미연결 · 생성형 AI 응답이 아니에요.<br>현재 분석 결과만 정해진 문장으로 설명해요.</p><div class="question-list">${[['why','왜 이 점수가 나왔나요?'],['duplicate','어떤 성분이 겹치나요?'],['limits','아직 확인하지 못한 정보는요?']].map(([id,q])=>`<button data-action="question" data-id="${id}" aria-controls="explanation-answer" aria-pressed="${explanation?.q===id&&explanation.fingerprint===a.fingerprint}">${q}${icon('arrow')}</button>`).join('')}</div><div id="explanation-answer" class="explanation-answer" role="status" aria-live="polite">${explanation?.fingerprint===a.fingerprint?explanationHTML(a,explanation.q):''}</div></section><section class="section evidence-section"><h2>분석 범위와 한계</h2><dl class="data-list"><div><dt>등록 제품 간 비교</dt><dd>${a.coverage.evaluatedPairs} / ${a.coverage.totalPairs}쌍</dd></div><div><dt>함량 미확인</dt><dd>${a.coverage.unknownAmounts}건</dd></div><div><dt>조건부 규칙 보류</dt><dd>${a.deferredRules.length}개</dd></div></dl><p class="body-muted">복용 시간·실제 섭취량·개인 조건은 확인하지 않았어요. 함량이 없다는 뜻은 0이라는 뜻이 아니에요.</p><button class="link-row" data-action="coverage">보류된 규칙과 데이터 확인 ${icon('arrow')}</button></section><footer class="footer-note">원본 ${esc(analysisDataset.versions.cart)} · ${esc(a.score.policyVersion)}<br>이 화면의 모든 제품은 DEMO예요.</footer></section>`}
function explanationHTML(a,q){let text='';if(q==='why')text=a.score.value===null?'현재는 비교 가능한 제품 쌍이 없어 숫자 점수를 표시하지 않아요.':`기준 ${a.score.baseline}점에서 고유 원인 ${a.score.deductions.length}가지의 감점 ${a.score.rawDeduction}점을 반영해 ${a.score.value}점이에요.${a.score.deductions.length?' 같은 성분 관계는 여러 제품에서 발견돼도 가장 큰 감점 한 번만 적용해요.':' 등록된 주의 관계가 없다는 뜻이며, 안전함을 뜻하지 않아요.'}`;else if(q==='duplicate')text=a.duplicates.length?`${a.duplicates.map(d=>`${d.name} (${d.productIds.length}개 제품)`).join(', ')}이 겹쳐요. 함량과 일일 섭취량이 없어 총량이나 과다 여부는 판단하지 않았어요.`:'현재 등록 성분에서 중복은 확인되지 않았어요. 미등록 성분이나 실제 제품 전체를 확인한 결과는 아니에요.';else text=`함량 ${a.coverage.unknownAmounts}건이 미확인이에요. 별도 조건부 규칙 ${a.deferredRules.length}개는 개인 조건·복용 정보가 부족해 보류했어요. 복용 시간이나 실제 섭취량에 관한 결론은 내리지 않아요.`;return `<div class="explanation-content"><span class="label">규칙 기반 안내 · AI 생성 아님</span><p>${esc(text)}</p><span class="meta">${q==='why'&&a.score.deductions.length?`근거: ${esc([...new Set(a.score.deductions.flatMap(d=>d.ruleIds))].join(', '))}`:'근거: 현재 조합의 등록 성분과 분석 범위'}</span></div>`}
function selectedReplacement(){const sources=cart.filter(i=>getReplacementCandidates(cart,i.productId,analysisDataset).length);if(!sources.some(i=>i.productId===replacementSource))replacementSource=sources[0]?.productId;const candidates=replacementSource?getReplacementCandidates(cart,replacementSource,analysisDataset):[];if(!candidates.some(c=>c.product.product_id===replacementTarget))replacementTarget=candidates[0]?.product.product_id;return {sources,candidates,candidate:candidates.find(c=>c.product.product_id===replacementTarget)}}
function optimizeScreen(){const {sources,candidates,candidate}=selectedReplacement();if(!candidate)return `<section class="screen">${topbar('제품 교체 비교',true)}<div class="empty-state"><h3>비교 가능한 후보가 없어요</h3><p>공통 등록 성분이 있는 보충제만 후보가 돼요.<br>복용약은 교체하지 않아요.</p><button class="secondary-button" data-action="go" data-id="cart">조합함으로 돌아가기</button></div></section>`;const c=candidate.comparison;const source=byId.get(replacementSource),target=byId.get(replacementTarget);return `<section class="screen optimize-screen">${topbar('제품 교체 비교',true)}<p class="body-muted">같은 분석 규칙으로 변경 전후를 비교해요.</p><div class="replacement-selectors"><label class="field-label">교체할 보충제<select id="replacement-source">${sources.map(i=>`<option value="${i.productId}" ${replacementSource===i.productId?'selected':''}>${esc(byId.get(i.productId).name)}</option>`).join('')}</select></label><label class="field-label">비교할 후보<select id="replacement-target">${candidates.map(x=>`<option value="${x.product.product_id}" ${replacementTarget===x.product.product_id?'selected':''}>${esc(byId.get(x.product.product_id).name)}</option>`).join('')}</select></label></div><div class="comparison-panel"><div class="comparison-scores"><div><span>현재 구성</span><strong>${c.before.score.value??'—'}<small>점</small></strong></div><svg class="comparison-arrow" viewBox="0 0 48 24" aria-hidden="true"><path d="M2 12h40m-8-8 8 8-8 8" pathLength="100"/></svg><div><span>변경 구성</span><strong class="after-value" data-compare="${c.after.score.value??''}">${c.after.score.value??'—'}<small>점</small></strong></div></div><p class="comparison-delta">${c.scoreDelta===null?'비교 정보 부족':c.scoreDelta===0?'점수 차이 없음':`시연 비교 지표 ${c.scoreDelta>0?'+':''}${c.scoreDelta}점`}</p><div class="replacement-products"><div>${thumb(source)}<strong>${esc(source.name)}</strong><p>${esc(source.subtitle)}</p></div>${icon('arrow')}<div>${thumb(target)}<strong>${esc(target.name)}</strong><p>${esc(target.subtitle)}</p></div></div><p class="section-note">함량·효능을 비교한 값이 아니에요.</p></div><section class="section"><h2>무엇이 달라지나요?</h2><div class="change-list"><div><span class="change-marker">−</span><p><strong>매칭이 사라지는 원인 ${c.removedCauses.length}가지</strong><span>${c.removedCauses.length?esc(c.removedCauses.map(d=>`${d.ingredientNames.join(' · ')} (${d.ruleIds.join(', ')})`).join(', ')):'해당 없음'}</span></p></div><div><span class="change-marker">+</span><p><strong>새로 매칭되는 원인 ${c.addedCauses.length}가지</strong><span>${c.addedCauses.length?esc(c.addedCauses.map(d=>`${d.ingredientNames.join(' · ')} (${d.ruleIds.join(', ')})`).join(', ')):'등록 규칙 기준으로 없음'}</span></p></div></div><div class="notice">변경 후에도 함량 ${c.after.coverage.unknownAmounts}건과 개인 복용 조건은 미확인이에요. 100점도 안전함을 보장하지 않아요.</div></section><div class="button-stack"><button class="primary-button" data-action="apply-replacement">변경 조합 적용하기 ${icon('arrow')}</button></div><p class="section-note">공통 등록 성분 기준의 비교예요. 효능의 동등성이나 복용 추천을 뜻하지 않으며 복용약은 변경하지 않아요.</p></section>`}
function afterAnalysisRender(){cancelAnimationFrame(comparisonFrame);if(screen==='optimize'){const target=$('[data-compare]');const c=selectedReplacement().candidate?.comparison;if(target&&c?.after.score.value!==null){const from=c.before.score.value??0,to=c.after.score.value,start=performance.now();function frame(now){const p=reduced.matches?1:Math.min((now-start)/600,1);target.innerHTML=`${Math.round(from+(to-from)*(1-Math.pow(1-p,3)))}<small>점</small>`;if(p<1)comparisonFrame=requestAnimationFrame(frame)}comparisonFrame=requestAnimationFrame(frame)}}}
function openSheet(title,html){if(!$('#sheet').open){sheetOpener=document.activeElement;sheetScroll=window.scrollY;document.body.style.position='fixed';document.body.style.top=`-${sheetScroll}px`;document.body.style.width='100%';$('#sheet').showModal()}$('#sheet-title').textContent=title;$('#sheet-body').innerHTML=html;$('#sheet').scrollTop=0;$('#sheet').querySelector('[data-action="close-sheet"]').focus()}
function closeSheet(){if($('#sheet').open)$('#sheet').close()}
$('#sheet').addEventListener('close',()=>{document.body.style.position='';document.body.style.top='';document.body.style.width='';window.scrollTo(0,sheetScroll);if(sheetOpener?.isConnected)sheetOpener.focus({preventScroll:true});else $('#main').focus({preventScroll:true})});
$('#sheet').addEventListener('click',e=>{if(e.target===$('#sheet')){const r=$('#sheet').getBoundingClientRect();if(e.clientY<r.top||e.clientX<r.left||e.clientX>r.right)closeSheet()}});
function showProduct(id){const p=byId.get(id);const inCart=cart.some(i=>i.productId===id);openSheet('제품 상세',`<div class="sheet-product">${thumb(p)}<div><span class="badge">DEMO</span><h3>${esc(p.name)}</h3><p>${esc(p.subtitle)}</p></div></div><h3>등록 성분</h3><dl class="data-list">${p.ingredients.map((i,n)=>`<div><dt>${esc(p.ingredientNames[n])}</dt><dd>${i.amount===null?'함량 미등록':`${esc(i.amount)} ${esc(i.unit)}`}</dd></div>`).join('')}</dl><div class="notice">가상의 시연용 구성과 패키지예요. 함량을 0으로 해석하거나 실제 제품의 성분으로 추정하지 않아요.${p.category==='medication'?'<p>복용약은 교체 비교 대상에 포함하지 않아요.</p>':''}</div><div class="button-stack"><button class="${inCart?'secondary-button':'primary-button'}" data-action="${inCart?'sheet-cancel':'sheet-add'}" data-id="${id}">${icon(inCart?'x':'plus')}${inCart?'담기 취소':'조합함에 담기'}</button><button class="secondary-button" data-action="close-sheet">닫고 돌아가기</button></div>`)}
function showExample(id){const e=examples.find(x=>x.id===id);const a=analyzeCart(itemsFor(e.ids),analysisDataset);openSheet('예시 조합 살펴보기',`<span class="badge">DEMO · 복용 추천 아님</span><h3 style="margin:16px 0 10px">${e.title}</h3><p class="body-muted">${e.description}</p><ul class="product-list">${e.ids.map(id=>`<li class="product-row">${thumb(byId.get(id))}<span class="product-copy"><strong>${esc(byId.get(id).name)}</strong><p>${esc(byId.get(id).subtitle)}</p></span></li>`).join('')}</ul><div class="notice">시연 비교 지표 <strong>${a.score.value} / 100</strong><p>적용하면 현재 조합을 이 예시로 바꿔요. 100점도 의학적 안전성을 보장하지 않아요.</p></div><div class="button-stack"><button class="primary-button" data-action="apply-example" data-id="${id}">이 구성으로 살펴보기 ${icon('arrow')}</button></div>`)}
function changeCart(next,message){previousCart=cart.map(i=>({...i}));undoCart=previousCart;cart=normalizeCart(next);explanation=null;selectedCause=null;const durable=persist();render();toast(message+(durable?'':' · 저장 불가, 이번 화면에서만 유지'),true);announce(`조합이 변경됐어요. 시연 비교 지표 ${result().score.value??'분석 정보 부족'}`)}
function add(id){const old=cart.find(i=>i.productId===id);if(old?.quantity>=99){toast('용기는 최대 99개까지 담을 수 있어요.');return}const pos=window.scrollY;changeCart(old?cart.map(i=>i.productId===id?{...i,quantity:i.quantity+1}:i):[...cart,{productId:id,quantity:1}],`${byId.get(id).name} 담았어요`);window.scrollTo(0,pos);const addedButton=document.querySelector(`[data-action="cancel-add"][data-id="${id}"]`);addedButton?.classList.add('just-added');addedButton?.focus({preventScroll:true});document.querySelector('.nav-item[href="#cart"]')?.classList.add('pulse')}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const {action,id}=b.dataset;if(action==='go')navigate(id);else if(action==='product')showProduct(id);else if(action==='add')add(id);else if(action==='cancel-add')cancelAdd(id);else if(action==='sheet-cancel'){closeSheet();cancelAdd(id);}else if(action==='sheet-add'){closeSheet();add(id)}else if(action==='close-sheet')closeSheet();else if(action==='example')showExample(id);else if(action==='apply-example'){closeSheet();changeCart(itemsFor(examples.find(x=>x.id===id).ids),'예시 조합을 적용했어요');navigate('cart')}else if(action==='category'){category=id;query='';medications=false;navigate('explore')}else if(action==='medications'){medications=true;query='';navigate('explore')}else if(action==='filter'){category=id;render()}else if(action==='mode'){medications=id==='medication';render()}else if(action==='clear-search'){query='';category='전체';render();$('#catalog-search')?.focus()}else if(action==='home-tab'){homeTab=id;const y=window.scrollY;render();window.scrollTo(0,y)}else if(action==='undo'&&undoCart){const last=undoCart;undoCart=null;cart=last;persist();render();toast('이전 조합으로 되돌렸어요')}else featureAction(action,id,b)});
document.addEventListener('submit',e=>{const form=e.target;if(form.dataset.form==='home-search'){e.preventDefault();query=new FormData(form).get('query');category='전체';medications=false;navigate('explore')}else if(form.dataset.form==='search')e.preventDefault();else featureSubmit(e)});
document.addEventListener('input',e=>{if(e.target.id==='catalog-search'){query=e.target.value;updateCatalog()}else if(e.target.id==='combination-name')e.target.setCustomValidity('')});
document.addEventListener('change',e=>{if(e.target.id==='sort'){listSort=e.target.value;updateCatalog()}else featureChange(e)});
function cancelAdd(id){const y=window.scrollY;changeCart(cart.filter(i=>i.productId!==id),`${byId.get(id).name} 담기를 취소했어요`);window.scrollTo(0,y);document.querySelector(`[data-action="add"][data-id="${id}"]`)?.focus({preventScroll:true})}
function featureAction(action,id){
 if(action==='remove'){const y=window.scrollY;changeCart(cart.filter(i=>i.productId!==id),`${byId.get(id).name} 삭제했어요`);window.scrollTo(0,y)}
 else if(action==='quantity-plus'||action==='quantity-minus'){const delta=action==='quantity-plus'?1:-1;const y=window.scrollY;changeCart(cart.map(i=>i.productId===id?{...i,quantity:Math.max(1,Math.min(99,i.quantity+delta))}:i),'용기 수량을 변경했어요');window.scrollTo(0,y);document.querySelector(`[data-action="${action}"][data-id="${id}"]`)?.focus({preventScroll:true})}
 else if(action==='score-guide'){const a=result();openSheet('점수 계산 가이드',`<span class="badge">${SCORING_POLICY.version}</span><h3 style="margin-top:16px">안전 등급이 아닌 비교용 숫자예요</h3><p class="body-muted" style="margin-top:12px">100에서 고유한 성분 관계의 감점을 빼요. 같은 원인은 가장 큰 감점 한 번만 반영해요.</p><dl class="data-list"><div><dt>정보 확인 · info</dt><dd>−${SCORING_POLICY.weights.info}점</dd></div><div><dt>주의 확인 · caution</dt><dd>−${SCORING_POLICY.weights.caution}점</dd></div><div><dt>우선 확인 · high</dt><dd>−${SCORING_POLICY.weights.high}점</dd></div></dl><div class="notice"><p>가중치는 앱의 시연 정책이며 임상 위험도·확률이 아니에요. 시너지 가점은 없어요.</p><p>함량 미확인 ${a.coverage.unknownAmounts}건, 조건부 규칙 ${a.deferredRules.length}개는 보류 중이에요. 등록 규칙이 없는 관계를 안전하다고 판단하지 않아요.</p></div>`)}
 else if(action==='save'){openSheet('조합 저장하기',`<form data-form="save"><label class="field-label" for="combination-name">조합 이름</label><p id="save-error" role="alert" class="save-error" hidden></p><input class="text-input" id="combination-name" name="name" maxlength="40" required value="나의 조합 ${saved.length+1}"><p class="body-muted" style="margin-top:12px">${cart.length}개 제품 · 시연 비교 지표 ${result().score.value??'—'}<br>이 브라우저에만 저장돼요.</p><div class="button-stack"><button class="primary-button" type="submit">저장하기</button></div></form>`)}
 else if(action==='restore'){const s=saved.find(x=>x.id===id);if(s){changeCart(s.items.map(i=>({...i})),'저장한 조합을 복원했어요');navigate('cart')}}
 else analysisAction(action,id);
}
function featureSubmit(e){if(e.target.dataset.form==='save'){e.preventDefault();const name=String(new FormData(e.target).get('name')||'').trim();if(!name){$('#combination-name').setCustomValidity('조합 이름을 입력해주세요.');$('#combination-name').reportValidity();return}const entry={id:crypto.randomUUID(),name,items:cart.map(i=>({...i}))};saved.unshift(entry);if(!persist()){saved.shift();$('#save-error').hidden=false;$('#save-error').textContent='저장 공간에 접근할 수 없어 저장하지 못했어요. 브라우저 설정을 확인해주세요.';return}closeSheet();render();toast('조합을 저장했어요 · 내 정보에서 복원')}}
function featureChange(e){if(e.target.id==='replacement-source'){replacementSource=e.target.value;replacementTarget=null;render();$('#replacement-source').focus({preventScroll:true})}else if(e.target.id==='replacement-target'){replacementTarget=e.target.value;render();$('#replacement-target').focus({preventScroll:true})}}
function analysisAction(action,id){const a=result();if(action==='relation'){selectedCause=a.findings.find(f=>f.ruleId===id)?.causeKey;const y=window.scrollY;render();window.scrollTo(0,y);document.querySelector(`[data-action="relation"][data-id="${id}"]`)?.focus({preventScroll:true})}
 else if(action==='evidence'){const f=a.findings.find(f=>f.ruleId===id);if(!f)return;const deduction=a.score.deductions.find(d=>d.causeKey===f.causeKey);const related=a.findings.filter(x=>x.causeKey===f.causeKey);openSheet('관계의 근거',`<div class="section-heading"><span class="badge ${f.severity==='info'?'blue':'warn'}">${esc(f.ruleId)} · ${esc(f.severity)}</span><strong class="deduction">−${deduction.points}<small>점 / 고유 원인</small></strong></div><h3>${esc(f.ingredientNames.join(' · '))}</h3><p class="rule-message">${esc(f.message)}</p><div class="notice"><p><strong>등록 규칙의 설명이에요.</strong><br>${esc(f.triggerMeaning)}</p><p>${esc(f.detailedEvaluation.reason)}</p><p>개인 복용 지침이 아니에요. 실제 제형·함량·복용 시간은 의료진·약사와 확인해주세요.</p></div><dl class="data-list"><div><dt>데이터셋 근거 수준</dt><dd>${esc(f.evidenceLevel??'미등록')}</dd></div><div><dt>연결된 규칙</dt><dd>${esc(deduction.ruleIds.join(', '))}</dd></div></dl><h3>해당 제품</h3>${related.map(x=>`<p class="body-muted" style="margin:10px 0">${esc(x.productIds.map(id=>byId.get(id).name).join(' + '))}</p>`).join('')}<h3 style="margin-top:22px">등록 출처</h3>${sourcesHTML(f)}<p class="section-note">근거 수준은 원본 JSON의 표기이며, Fitmate가 새로 평가한 등급이 아니에요. 감점 수치는 임상 자료가 아닌 별도 시연 정책이에요.</p>`)}
 else if(action==='question'){explanation={q:id,fingerprint:a.fingerprint};const box=$('#explanation-answer');box.innerHTML=explanationHTML(a,id);document.querySelectorAll('[data-action="question"]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.id===id)));box.scrollIntoView({block:'nearest',behavior:reduced.matches?'instant':'smooth'})}
 else if(action==='coverage'){openSheet('데이터와 보류된 규칙',`<div class="notice">제품 ${analysisDataset.products.length}개 · 주 규칙 ${analysisDataset.rules.length}개<br>함량 미확인 ${a.coverage.unknownAmounts}건 · 미지원 필수 규칙 ${a.coverage.skippedRules}개</div><p class="body-muted" style="margin:18px 0">아래 조건부 규칙 ${a.deferredRules.length}개는 점수에 반영하지 않았어요.</p>${a.deferredRules.map(d=>`<details class="deferred-rule"><summary>${esc(d.id)} · ${d.type==='personal_condition_check'?'개인 조건':'병용 조건'}</summary><p>${esc(d.reason)}</p>${d.sourceUrls.map((url,i)=>`<a class="text-link" target="_blank" rel="noopener noreferrer" href="${esc(url)}">등록 출처 ${i+1} ↗</a>`).join('')}</details>`).join('')}<div class="button-stack"><a class="secondary-button" href="./data/cart_interactions_dataset.json" target="_blank">원본 주 데이터 JSON 보기</a></div>`)}
 else if(action==='apply-replacement'){const candidate=selectedReplacement().candidate;if(!candidate)return;const delta=candidate.comparison.scoreDelta;changeCart(candidate.items,`구성을 변경했어요${delta===null?'':` · ${delta>0?'+':''}${delta}점`}`);navigate('cart')}
}
window.addEventListener('hashchange',()=>{const restore=screen==='explore'&&location.hash===`#${exploreReturn}`;if(location.hash==='#explore'&&screen!=='explore'){exploreReturn=screen;exploreReturnScroll=window.scrollY;}closeSheet();render();window.scrollTo(0,restore?exploreReturnScroll:0);$('#main').focus({preventScroll:true})});
render();
